//! Guarantees `static/` exists before `RustEmbed`'s derive macro scans it
//! (`src/gateway.rs`'s `WebAssets`), so `cargo build`/`test`/`clippy` never
//! fail on a fresh checkout where `npm run bundle` (apps/fgos-gateway/web/)
//! hasn't produced the web UI yet -- `static/` is gitignored. Minimal port
//! of the reference implementation herdr-gateway's own `build.rs`: only the
//! directory guarantee, per D14 of docs/history/herdr-web-dashboard-plan-
//! realignment/CONTEXT.md -- that decision never asked for the sibling
//! fingerprint/git-sha logic herdr-gateway's own build.rs also carries.

fn main() {
    std::fs::create_dir_all("static").expect("create static/ dir for embedding");
}

//! Cloudflare Access JWT verification — opt-in, additive, fail-closed
//! (tsk-6arn, D8 of docs/history/herdr-web-dashboard/CONTEXT.md).
//!
//! Ported from the reference implementation `/home/vantt/projects/
//! herdr-gateway` (crate herdr-go, `src/web/cf_access.rs`) — the
//! crypto/JWT-verification core is copied wholesale, unmodified in
//! substance: this is a security-critical, already-audited
//! implementation, and writing a new one from scratch would be strictly
//! worse, not better. Dependency versions differ from the reference
//! (`jsonwebtoken` 9->11, `reqwest` 0.12->0.13 with its TLS feature
//! renamed `rustls-tls`->`rustls`) -- resolved via a real `cargo add
//! --dry-run` at this item's own validating pass, not copied from the
//! reference's own (older) `Cargo.toml`.
//!
//! When an operator configures `gateway.cfAccessTeamDomain` +
//! `gateway.cfAccessAud` (`~/.fgos/config.json`), a request that arrives
//! already authenticated by Cloudflare Access at the edge carries a
//! `Cf-Access-Jwt-Assertion` header. This module turns that header into a
//! verified identity, or an error — never a partial pass.
//!
//! The single security property this module exists to guarantee: the
//! header's claims are trusted **only** after the JWT's RS256 signature
//! verifies against Cloudflare's published JWKS, and `iss`/`aud`/`exp`/
//! `nbf` all check out. Any single mismatch is an `Err`. Trusting the raw
//! header without a signature check is exactly the hole this feature's
//! threat model warns about.
//!
//! Wired into `require_token` (`gateway.rs`): checked ONLY when Bearer
//! (layer 1, already shipped) did not already pass — additive, D8's own
//! "cộng dồn, không loại trừ lẫn nhau", never a replacement. On any
//! failure (verifier absent, header absent, signature/claims invalid),
//! this falls through to the SAME 401 `require_token` already returns for
//! a missing/invalid Bearer token — cf-access shares layer 1's own HTTP
//! status convention (`tsk-4qf`'s own locked decision for THIS gate),
//! not the "404 câm" framing tsk-18to's original description carried
//! from a cookie-session design (`tsk-k4v`) that never shipped.

use std::collections::HashMap;
use std::sync::Mutex;
use std::time::{Duration, Instant};

use jsonwebtoken::{decode, decode_header, Algorithm, DecodingKey, Validation};
use serde::Deserialize;

/// Path (relative to the team domain) of Cloudflare Access's JWKS endpoint.
const CERTS_PATH: &str = "cdn-cgi/access/certs";
/// How long a fetched JWKS is trusted before a refetch. Cloudflare rotates
/// signing keys and keeps the previous ones live well beyond this window, so an
/// hour bounds staleness without refetching on every request.
const JWKS_TTL: Duration = Duration::from_secs(3600);

/// Why a `Cf-Access-Jwt-Assertion` was not accepted. Every variant is a hard
/// "not authenticated" — callers treat all of them identically (fail closed).
#[derive(Debug)]
pub enum CfAccessError {
    /// The JWKS could not be fetched (network, HTTP status, or malformed body).
    Fetch(String),
    /// The token header carried no `kid`, so no signing key can be selected.
    MissingKid,
    /// The token's `kid` is not in the (freshly fetched) JWKS.
    UnknownKid,
    /// Signature, `iss`, `aud`, `exp`, or `nbf` failed validation.
    Invalid(String),
    /// Signature and claims verified, but the token carried no usable identity
    /// (neither `email` nor `sub`).
    NoIdentity,
}

impl std::fmt::Display for CfAccessError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CfAccessError::Fetch(e) => write!(f, "CF Access JWKS fetch failed: {e}"),
            CfAccessError::MissingKid => write!(f, "CF Access token has no kid header"),
            CfAccessError::UnknownKid => write!(f, "CF Access token kid not in JWKS"),
            CfAccessError::Invalid(e) => write!(f, "CF Access token failed verification: {e}"),
            CfAccessError::NoIdentity => write!(f, "CF Access token carried no identity claim"),
        }
    }
}

impl std::error::Error for CfAccessError {}

/// The subset of a JWKS document this verifier needs. Cloudflare sends more
/// fields per key (`kty`, `alg`, `use`, `x5c`, …); serde ignores the rest.
#[derive(Debug, Deserialize)]
struct Jwks {
    keys: Vec<Jwk>,
}

#[derive(Debug, Deserialize)]
struct Jwk {
    kid: String,
    /// RSA modulus, base64url (as `DecodingKey::from_rsa_components` expects).
    n: String,
    /// RSA public exponent, base64url.
    e: String,
}

/// Claims read out of a verified token. `exp`/`nbf`/`iss`/`aud` are validated by
/// `jsonwebtoken` itself and so are not re-read here.
#[derive(Debug, Deserialize)]
struct CfClaims {
    #[serde(default)]
    email: Option<String>,
    #[serde(default)]
    sub: Option<String>,
}

/// In-memory JWKS cache: signing keys by `kid`, plus when they were fetched.
struct JwksCache {
    keys: HashMap<String, DecodingKey>,
    fetched_at: Option<Instant>,
}

/// Verifies `Cf-Access-Jwt-Assertion` headers for one configured CF Access
/// application. Holds the reqwest client, the expected team domain (= JWKS
/// origin and expected `iss`), the expected `aud` tag, and the JWKS cache.
pub struct CfAccessVerifier {
    client: reqwest::Client,
    team_domain: String,
    aud: String,
    cache: Mutex<JwksCache>,
}

// Manual impl (not `#[derive(Debug)]`): `Mutex<JwksCache>` holding
// `DecodingKey`s doesn't need a real Debug bound threaded through just to
// let `GatewayConfig` (which wraps this in `Arc<Option<CfAccessVerifier>>`)
// keep its own `#[derive(Debug)]`. Never prints key material -- there is
// none to print (only the team domain, which is not secret).
impl std::fmt::Debug for CfAccessVerifier {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CfAccessVerifier").field("team_domain", &self.team_domain).finish_non_exhaustive()
    }
}

impl CfAccessVerifier {
    /// Build a verifier. `team_domain` is the full origin
    /// (e.g. `https://team.cloudflareaccess.com`); `aud` is the Access
    /// Application Audience tag.
    pub fn new(client: reqwest::Client, team_domain: String, aud: String) -> Self {
        // Normalize once so the JWKS fetch and the `iss` check always agree: a
        // trailing slash on the configured domain must not let the fetch succeed
        // while the `iss` comparison silently never matches.
        let team_domain = team_domain.trim_end_matches('/').to_string();
        CfAccessVerifier {
            client,
            team_domain,
            aud,
            cache: Mutex::new(JwksCache { keys: HashMap::new(), fetched_at: None }),
        }
    }

    fn certs_url(&self) -> String {
        format!("{}/{}", self.team_domain, CERTS_PATH)
    }

    /// Verify a raw `Cf-Access-Jwt-Assertion` value. Returns the identity
    /// (`email` if present, else `sub`) only when the signature verifies against
    /// the cached JWKS and `iss`/`aud`/`exp`/`nbf` all pass.
    pub async fn verify(&self, assertion: &str) -> Result<String, CfAccessError> {
        let kid = decode_header(assertion).map_err(|e| CfAccessError::Invalid(e.to_string()))?.kid.ok_or(CfAccessError::MissingKid)?;
        let key = self.decoding_key(&kid).await?;
        verify_with_key(assertion, &key, &self.team_domain, &self.aud)
    }

    /// Resolve the signing key for `kid` from the cache, refetching the JWKS
    /// once if the cache is stale or unseeded. A *fresh* cache that lacks the
    /// `kid` is `UnknownKid` without a refetch — so a stream of bogus `kid`s
    /// cannot force a fetch per request.
    async fn decoding_key(&self, kid: &str) -> Result<DecodingKey, CfAccessError> {
        {
            let cache = self.cache.lock().unwrap();
            if let Some(at) = cache.fetched_at {
                if at.elapsed() < JWKS_TTL {
                    return cache.keys.get(kid).cloned().ok_or(CfAccessError::UnknownKid);
                }
            }
        }
        let jwks = self.fetch_jwks().await?;
        let mut keys = HashMap::new();
        for jwk in jwks.keys {
            if let Ok(dk) = DecodingKey::from_rsa_components(&jwk.n, &jwk.e) {
                keys.insert(jwk.kid, dk);
            }
        }
        let mut cache = self.cache.lock().unwrap();
        cache.keys = keys;
        cache.fetched_at = Some(Instant::now());
        cache.keys.get(kid).cloned().ok_or(CfAccessError::UnknownKid)
    }

    async fn fetch_jwks(&self) -> Result<Jwks, CfAccessError> {
        self.client
            .get(self.certs_url())
            .send()
            .await
            .map_err(|e| CfAccessError::Fetch(e.to_string()))?
            .error_for_status()
            .map_err(|e| CfAccessError::Fetch(e.to_string()))?
            .json::<Jwks>()
            .await
            .map_err(|e| CfAccessError::Fetch(e.to_string()))
    }
}

/// The pure verification step, isolated from the network so it can be tested
/// against a locally-generated key + hand-built JWT. RS256 only; `iss` must
/// equal `team_domain`; `aud` must contain `aud`; `exp`/`nbf` must be valid.
fn verify_with_key(assertion: &str, key: &DecodingKey, team_domain: &str, aud: &str) -> Result<String, CfAccessError> {
    let mut validation = Validation::new(Algorithm::RS256);
    validation.set_issuer(&[team_domain]);
    validation.set_audience(&[aud]);
    validation.validate_nbf = true;
    // `Validation::new` only seeds `exp` as required, so `iss`/`aud` would be
    // checked *if present* but a token omitting either would still pass. Require
    // all three so a missing `iss` or `aud` is an outright rejection.
    validation.set_required_spec_claims(&["exp", "iss", "aud"]);
    let claims = decode::<CfClaims>(assertion, key, &validation).map_err(|e| CfAccessError::Invalid(e.to_string()))?.claims;
    claims.email.filter(|s| !s.is_empty()).or_else(|| claims.sub.filter(|s| !s.is_empty())).ok_or(CfAccessError::NoIdentity)
}

