#[cfg(test)]
impl CfAccessVerifier {
    /// Test seam: seed the JWKS cache with a signing key so `verify` runs fully
    /// offline (what a real fetch would populate). Lets `gateway.rs`'s own
    /// tests prove the middleware wiring against a valid token without a live
    /// JWKS endpoint.
    pub(crate) fn seed_test_key(&self, kid: &str, key: DecodingKey) {
        let mut cache = self.cache.lock().unwrap();
        cache.keys.insert(kid.to_string(), key);
        cache.fetched_at = Some(Instant::now());
    }
}

/// Build a verifier whose cache is pre-seeded with the test signing key, plus a
/// freshly signed, fully valid token it will accept — the pair `gateway.rs`
/// needs to exercise the CF Access branch of `require_token` offline.
#[cfg(test)]
pub(crate) fn test_verifier_with_valid_token() -> (CfAccessVerifier, String) {
    use jsonwebtoken::{encode, EncodingKey, Header};
    use std::time::{SystemTime, UNIX_EPOCH};

    let verifier = CfAccessVerifier::new(reqwest::Client::new(), TEST_TEAM.to_string(), TEST_AUD.to_string());
    verifier.seed_test_key(TEST_KID, DecodingKey::from_rsa_components(TEST_N, TEST_E).unwrap());

    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();
    let claims = serde_json::json!({
        "iss": TEST_TEAM,
        "aud": [TEST_AUD],
        "sub": "user-sub-123",
        "email": "user@example.com",
        "exp": now + 3600,
        "nbf": now - 10,
        "iat": now - 10,
    });
    let mut header = Header::new(Algorithm::RS256);
    header.kid = Some(TEST_KID.to_string());
    let token = encode(&header, &claims, &EncodingKey::from_rsa_pem(TEST_PRIV_PEM.as_bytes()).unwrap()).unwrap();

    (verifier, token)
}

#[cfg(test)]
mod tests {
    use super::*;
    use jsonwebtoken::{encode, EncodingKey, Header};
    use serde::Serialize;
    use std::time::{SystemTime, UNIX_EPOCH};

    #[derive(Serialize)]
    struct TestClaims {
        iss: String,
        aud: Vec<String>,
        sub: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        email: Option<String>,
        exp: usize,
        nbf: usize,
        iat: usize,
    }

    fn now() -> usize {
        SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs() as usize
    }

    fn test_key() -> DecodingKey {
        DecodingKey::from_rsa_components(TEST_N, TEST_E).unwrap()
    }

    /// Sign a JWT (RS256, `kid=test-kid`) with the test private key. Generic so
    /// tests can sign either a `TestClaims` or a hand-built `serde_json::Value`
    /// that deliberately omits a claim.
    fn sign<T: Serialize>(claims: &T) -> String {
        let mut header = Header::new(Algorithm::RS256);
        header.kid = Some(TEST_KID.to_string());
        let key = EncodingKey::from_rsa_pem(TEST_PRIV_PEM.as_bytes()).unwrap();
        encode(&header, claims, &key).unwrap()
    }

    fn base_claims() -> TestClaims {
        let n = now();
        TestClaims {
            iss: TEST_TEAM.to_string(),
            aud: vec![TEST_AUD.to_string()],
            sub: "user-sub-123".to_string(),
            email: Some("user@example.com".to_string()),
            exp: n + 3600,
            nbf: n - 10,
            iat: n - 10,
        }
    }

    #[test]
    fn valid_token_returns_email_identity() {
        let token = sign(&base_claims());
        let id = verify_with_key(&token, &test_key(), TEST_TEAM, TEST_AUD).unwrap();
        assert_eq!(id, "user@example.com");
    }

    #[test]
    fn valid_token_without_email_falls_back_to_sub() {
        let mut claims = base_claims();
        claims.email = None;
        let token = sign(&claims);
        let id = verify_with_key(&token, &test_key(), TEST_TEAM, TEST_AUD).unwrap();
        assert_eq!(id, "user-sub-123");
    }

    #[test]
    fn tampered_signature_is_rejected() {
        let token = sign(&base_claims());
        // Flip one character of the signature segment: well-formed shape, wrong
        // signature. The verifier must not trust the (unchanged) claims.
        let mut parts: Vec<&str> = token.split('.').collect();
        let sig = parts[2].to_string();
        let flipped: String = sig
            .chars()
            .enumerate()
            .map(|(i, c)| if i == 0 && c != 'A' { 'A' } else if i == 0 { 'B' } else { c })
            .collect();
        parts[2] = &flipped;
        let tampered = parts.join(".");
        assert!(verify_with_key(&tampered, &test_key(), TEST_TEAM, TEST_AUD).is_err());
    }

    #[test]
    fn wrong_aud_is_rejected() {
        let mut claims = base_claims();
        claims.aud = vec!["some-other-aud".to_string()];
        let token = sign(&claims);
        assert!(verify_with_key(&token, &test_key(), TEST_TEAM, TEST_AUD).is_err());
    }

    #[test]
    fn wrong_iss_is_rejected() {
        let mut claims = base_claims();
        claims.iss = "https://attacker.cloudflareaccess.com".to_string();
        let token = sign(&claims);
        assert!(verify_with_key(&token, &test_key(), TEST_TEAM, TEST_AUD).is_err());
    }

    #[test]
    fn expired_token_is_rejected() {
        let mut claims = base_claims();
        let n = now();
        claims.iat = n - 100_000;
        claims.nbf = n - 100_000;
        claims.exp = n - 90_000;
        let token = sign(&claims);
        assert!(verify_with_key(&token, &test_key(), TEST_TEAM, TEST_AUD).is_err());
    }

    #[test]
    fn not_yet_valid_token_is_rejected() {
        let mut claims = base_claims();
        let n = now();
        claims.nbf = n + 100_000;
        claims.exp = n + 200_000;
        let token = sign(&claims);
        assert!(verify_with_key(&token, &test_key(), TEST_TEAM, TEST_AUD).is_err());
    }

    #[test]
    fn missing_aud_claim_is_rejected() {
        // A validly-signed token that omits `aud` entirely must be rejected —
        // `aud` is a required claim, not merely checked when present.
        let n = now();
        let claims = serde_json::json!({
            "iss": TEST_TEAM,
            "sub": "user-sub-123",
            "email": "user@example.com",
            "exp": n + 3600,
            "nbf": n - 10,
            "iat": n - 10,
        });
        let token = sign(&claims);
        assert!(verify_with_key(&token, &test_key(), TEST_TEAM, TEST_AUD).is_err());
    }

    #[test]
    fn missing_iss_claim_is_rejected() {
        // A validly-signed token that omits `iss` entirely must be rejected —
        // `iss` is a required claim, not merely checked when present.
        let n = now();
        let claims = serde_json::json!({
            "aud": [TEST_AUD],
            "sub": "user-sub-123",
            "email": "user@example.com",
            "exp": n + 3600,
            "nbf": n - 10,
            "iat": n - 10,
        });
        let token = sign(&claims);
        assert!(verify_with_key(&token, &test_key(), TEST_TEAM, TEST_AUD).is_err());
    }

    #[test]
    fn alg_none_token_is_rejected() {
        // Classic JWT bypass: an unsigned `alg: none` token whose claims are all
        // valid. RS256 is pinned, so decoding must reject it outright rather than
        // trust the unsigned claims. Built by hand because `jsonwebtoken` will
        // not encode `none`.
        use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
        let n = now();
        let header = serde_json::json!({ "alg": "none", "typ": "JWT", "kid": TEST_KID });
        let claims = serde_json::json!({
            "iss": TEST_TEAM,
            "aud": [TEST_AUD],
            "sub": "user-sub-123",
            "email": "user@example.com",
            "exp": n + 3600,
            "nbf": n - 10,
            "iat": n - 10,
        });
        let h = URL_SAFE_NO_PAD.encode(serde_json::to_vec(&header).unwrap());
        let p = URL_SAFE_NO_PAD.encode(serde_json::to_vec(&claims).unwrap());
        // `alg: none` carries an empty signature segment.
        let token = format!("{h}.{p}.");
        assert!(verify_with_key(&token, &test_key(), TEST_TEAM, TEST_AUD).is_err());
    }

    #[test]
    fn hs256_key_confusion_is_rejected() {
        // Classic RS256->HS256 confusion: forge an HS256 token using the RSA
        // public key's own modulus bytes as the HMAC secret. If the verifier ever
        // accepted HS256, this would validate against the public key. RS256 is
        // pinned, so it must be rejected.
        use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
        let n = now();
        let claims = base_claims_json(n);
        let secret = URL_SAFE_NO_PAD.decode(TEST_N).unwrap();
        let mut header = Header::new(Algorithm::HS256);
        header.kid = Some(TEST_KID.to_string());
        let token = encode(&header, &claims, &EncodingKey::from_secret(&secret)).unwrap();
        assert!(verify_with_key(&token, &test_key(), TEST_TEAM, TEST_AUD).is_err());
    }

    /// Fully-valid claim set as a JSON value, for tests that must control the
    /// header (and so cannot go through `sign`/`TestClaims`).
    fn base_claims_json(n: usize) -> serde_json::Value {
        serde_json::json!({
            "iss": TEST_TEAM,
            "aud": [TEST_AUD],
            "sub": "user-sub-123",
            "email": "user@example.com",
            "exp": n + 3600,
            "nbf": n - 10,
            "iat": n - 10,
        })
    }

    #[tokio::test]
    async fn trailing_slash_team_domain_still_matches_iss() {
        // An operator who configures the team domain with a trailing slash must
        // still authenticate tokens whose `iss` is the domain without the slash:
        // the JWKS fetch and the `iss` check both use the normalized value.
        let verifier = CfAccessVerifier::new(reqwest::Client::new(), format!("{TEST_TEAM}/"), TEST_AUD.to_string());
        verifier.seed_test_key(TEST_KID, test_key());
        let token = sign(&base_claims());
        let id = verifier.verify(&token).await.unwrap();
        assert_eq!(id, "user@example.com");
    }

    #[tokio::test]
    async fn verify_uses_fresh_cache_without_network() {
        // Seed a fresh cache, then verify end-to-end. A cache hit means no JWKS
        // fetch happens, so this exercises the full async path offline and
        // proves the cache is consulted rather than refetched every call.
        let verifier = CfAccessVerifier::new(reqwest::Client::new(), TEST_TEAM.to_string(), TEST_AUD.to_string());
        {
            let mut cache = verifier.cache.lock().unwrap();
            cache.keys.insert(TEST_KID.to_string(), test_key());
            cache.fetched_at = Some(Instant::now());
        }
        let token = sign(&base_claims());
        let id = verifier.verify(&token).await.unwrap();
        assert_eq!(id, "user@example.com");
    }

    #[tokio::test]
    async fn fresh_cache_missing_kid_is_unknown_kid_without_network() {
        // Fresh cache that lacks the token's kid must fail closed as UnknownKid
        // without attempting a fetch (the client points nowhere useful here).
        let verifier = CfAccessVerifier::new(reqwest::Client::new(), TEST_TEAM.to_string(), TEST_AUD.to_string());
        {
            let mut cache = verifier.cache.lock().unwrap();
            cache.fetched_at = Some(Instant::now());
        }
        let token = sign(&base_claims());
        assert!(matches!(verifier.verify(&token).await, Err(CfAccessError::UnknownKid)));
    }
}

//! tsk-7l9-2: fgOS gateway — the REST surface `docs/history/fgos-interface-daemon/`
//! locks (CONTEXT.md D1/D4/D5/D7/D8, `docs/contracts/fgos-gateway-api-v1.yaml`,
//! CTR010). Lives inside the `fgos-gateway` binary (D8) as a new async adapter
//! sitting beside the existing synchronous TUI/orchestrator code — nothing in
//! `app.rs`/`main.rs`'s TUI path changes shape or gains an async dependency.
//!
//! D7: this module is the SOLE place that spawns `fgos <verb>` on the
//! gateway's behalf (`spawn_fgos_verb`) — every route handler below funnels
//! through it, mirroring the CLI's own closed error taxonomy
//! (`src/state/store.mjs`'s `EXIT_CODES`) instead of inventing a new one.
//!
//! D4/D5: one auth token per machine, read from `~/.fgos/config.json`'s
//! `gateway.token` field (the global config file `docs/specs/distribution.md`
//! row 5b already establishes — this module only ever READS it; per that same
//! row ("not created by anything except fgos setup") it never writes or
//! creates the file itself, so a missing token is a startup refusal, not a
//! self-provisioned default).

