// MCP server + transport wiring
// ---------------------------------------------------------------------------

#[derive(Clone)]
pub struct FgosMcpServer {
    gateway: Arc<dyn VerbGateway>,
    root: PathBuf,
    // `#[tool_handler]`'s generated `call_tool`/`list_tools` call
    // `Self::tool_router()` fresh each dispatch (confirmed against
    // `rmcp-macros` 3.1.2's own `tool_handler.rs`), not this stored field --
    // so it is genuinely unread today. Kept anyway: it is the exact struct
    // shape rmcp's own canonical example (`examples/servers/.../counter.rs`)
    // requires for a `#[tool_router]`-eligible type, and stays forward-
    // compatible if a later rmcp version reads the instance field instead.
    #[allow(dead_code)]
    tool_router: ToolRouter<FgosMcpServer>,
}

#[tool_router]
impl FgosMcpServer {
    pub fn new(gateway: Arc<dyn VerbGateway>, root: PathBuf) -> Self {
        Self {
            gateway,
            root,
            tool_router: Self::tool_router(),
        }
    }

    #[tool(
        description = "Search the fgOS gateway's own OpenAPI contract for operations matching a query (path, operationId, or summary substring, case-insensitive). Omit `query` for the full operation list. Use this before `execute` to discover what's available."
    )]
    async fn search(&self, Parameters(SearchParams { query }): Parameters<SearchParams>) -> Result<CallToolResult, McpError> {
        match search_contract(&self.root, query).await {
            Ok(body) => Ok(CallToolResult::success(vec![ContentBlock::text(body)])),
            Err(msg) => Ok(CallToolResult::error(vec![ContentBlock::text(msg)])),
        }
    }

    #[tool(
        description = "Run Rhai script against the gateway's bound work-item functions (list_work, submit_work, get_work, move_work, ask_work, answer_work, take_work, return_work, approve_work, reject_work, ready_work, rollup, graph) — every call funnels through the same chokepoint the gateway's REST routes use. No filesystem, process, or network access is exposed beyond these bound functions."
    )]
    async fn execute(&self, Parameters(ExecuteParams { script }): Parameters<ExecuteParams>) -> Result<CallToolResult, McpError> {
        let gateway = self.gateway.clone();
        let outcome = tokio::task::spawn_blocking(move || run_script(gateway, &script))
            .await
            .map_err(|err| McpError::internal_error(format!("execute task panicked: {err}"), None))?;
        match outcome {
            Ok(body) => Ok(CallToolResult::success(vec![ContentBlock::text(body)])),
            Err(msg) => Ok(CallToolResult::error(vec![ContentBlock::text(msg)])),
        }
    }
}

#[tool_handler]
impl ServerHandler for FgosMcpServer {
    fn get_info(&self) -> ServerInfo {
        ServerInfo::new(ServerCapabilities::builder().enable_tools().build())
            .with_server_info(Implementation::from_build_env())
            .with_protocol_version(ProtocolVersion::V_2025_06_18)
            .with_instructions(
                "fgOS gateway Code Mode surface. Use `search` to discover the gateway's own API, then `execute` to run Rhai script against the bound work-item functions -- 2 tools total, cutting round-trips versus one MCP tool per REST endpoint.".to_string(),
            )
    }
}

/// Builds the MCP transport service ready to `.nest_service(...)` onto the
/// gateway's existing axum router (`gateway.rs::build_router`) — same
/// port/process, per D1.
pub fn build_mcp_service(
    gateway: Arc<dyn VerbGateway>,
    root: PathBuf,
) -> StreamableHttpService<FgosMcpServer, LocalSessionManager> {
    StreamableHttpService::new(
        move || Ok(FgosMcpServer::new(gateway.clone(), root.clone())),
        LocalSessionManager::default().into(),
        StreamableHttpServerConfig::default(),
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    struct FakeGateway {
        response: Result<serde_json::Value, String>,
    }

    impl VerbGateway for FakeGateway {
        fn run_verb(&self, _args: &[String]) -> Result<serde_json::Value, crate::gateway::GatewayError> {
            match &self.response {
                Ok(v) => Ok(v.clone()),
                Err(msg) => Err(crate::gateway::GatewayError::validation(msg.clone())),
            }
        }
    }

    fn fake(response: Result<serde_json::Value, String>) -> Arc<dyn VerbGateway> {
        Arc::new(FakeGateway { response })
    }

    struct CapturingGateway {
        captured: std::sync::Mutex<Vec<Vec<String>>>,
        response: Result<serde_json::Value, String>,
    }

    impl VerbGateway for CapturingGateway {
        fn run_verb(&self, args: &[String]) -> Result<serde_json::Value, crate::gateway::GatewayError> {
            self.captured.lock().unwrap().push(args.to_vec());
            match &self.response {
                Ok(v) => Ok(v.clone()),
                Err(msg) => Err(crate::gateway::GatewayError::validation(msg.clone())),
            }
        }
    }

    #[test]
    fn tool_router_advertises_exactly_search_and_execute() {
        let router = FgosMcpServer::tool_router();
        let names: Vec<String> = router.list_all().into_iter().map(|t| t.name.to_string()).collect();
        assert_eq!(names.len(), 2, "expected exactly 2 tools, found {names:?}");
        assert!(names.contains(&"search".to_string()));
        assert!(names.contains(&"execute".to_string()));
    }

    #[tokio::test]
    async fn search_with_no_query_returns_every_operation() {
        let root = std::env::temp_dir().join(format!("fgos-mcp-test-{}-{}", std::process::id(), line!()));
        std::fs::create_dir_all(root.join("docs/contracts")).unwrap();
        std::fs::write(
            root.join("docs/contracts/fgos-gateway-api-v1.yaml"),
            "openapi: 3.1.0\npaths:\n  /work:\n    get:\n      operationId: listWork\n      summary: List work items\n  /ready:\n    get:\n      operationId: getReady\n      summary: Ready frontier\n",
        )
        .unwrap();

        let body = search_contract(&root, None).await.unwrap();
        let parsed: Vec<Operation> = serde_json::from_str(&body).unwrap();
        assert_eq!(parsed.len(), 2);

        std::fs::remove_dir_all(&root).ok();
    }

    #[tokio::test]
    async fn search_with_a_query_matching_nothing_returns_an_empty_result_not_an_error() {
        let root = std::env::temp_dir().join(format!("fgos-mcp-test-{}-{}", std::process::id(), line!()));
        std::fs::create_dir_all(root.join("docs/contracts")).unwrap();
        std::fs::write(
            root.join("docs/contracts/fgos-gateway-api-v1.yaml"),
            "openapi: 3.1.0\npaths:\n  /work:\n    get:\n      operationId: listWork\n      summary: List work items\n",
        )
        .unwrap();

        let body = search_contract(&root, Some("zzz-no-such-operation".to_string())).await.unwrap();
        let parsed: Vec<Operation> = serde_json::from_str(&body).unwrap();
        assert!(parsed.is_empty());

        std::fs::remove_dir_all(&root).ok();
    }

    #[tokio::test]
    async fn search_query_matches_case_insensitively_on_path_and_summary() {
        let root = std::env::temp_dir().join(format!("fgos-mcp-test-{}-{}", std::process::id(), line!()));
        std::fs::create_dir_all(root.join("docs/contracts")).unwrap();
        std::fs::write(
            root.join("docs/contracts/fgos-gateway-api-v1.yaml"),
            "openapi: 3.1.0\npaths:\n  /work:\n    get:\n      operationId: listWork\n      summary: List work items\n  /ready:\n    get:\n      operationId: getReady\n      summary: Ready frontier\n",
        )
        .unwrap();

        let body = search_contract(&root, Some("READY".to_string())).await.unwrap();
        let parsed: Vec<Operation> = serde_json::from_str(&body).unwrap();
        assert_eq!(parsed.len(), 1);
        assert_eq!(parsed[0].operation_id, "getReady");

        std::fs::remove_dir_all(&root).ok();
    }

    #[tokio::test]
    async fn execute_empty_script_returns_cleanly_rather_than_hanging() {
        let gateway = fake(Ok(json!({"ok": true})));
        let result = tokio::task::spawn_blocking(move || run_script(gateway, "")).await.unwrap();
        assert!(result.is_ok());
    }

    #[tokio::test]
    async fn execute_an_infinite_loop_fails_fast_instead_of_hanging_forever() {
        let gateway = fake(Ok(json!({"ok": true})));
        let script = "let x = 0; loop { x += 1; }";
        let result = tokio::task::spawn_blocking(move || run_script(gateway, script)).await.unwrap();
        assert!(result.is_err(), "an unbounded loop must be stopped by the operation limit, not run forever");
        assert!(
            result.unwrap_err().contains("Too many operations"),
            "the failure should be the operation-limit error, not some other unrelated error"
        );
    }

    #[tokio::test]
    async fn execute_a_print_flood_does_not_grow_the_captured_output_past_the_byte_cap() {
        let gateway = fake(Ok(json!({"ok": true})));
        // Each iteration prints a 1024-byte line; enough iterations to
        // exceed MCP_EXECUTE_MAX_OUTPUT_BYTES (256 KiB) well before hitting
        // the operation limit (500_000), so this proves the byte cap fires
        // on its own rather than being masked by the operation limit.
        let script = r#"
            let line = "";
            for i in range(0, 1024) { line += "x"; }
            for i in range(0, 500) { print(line); }
        "#;
        let result = tokio::task::spawn_blocking(move || run_script(gateway, script)).await.unwrap();
        let output = result.expect("a bounded print flood should still complete successfully");
        assert!(
            output.len() <= MCP_EXECUTE_MAX_OUTPUT_BYTES + 4096,
            "captured output ({} bytes) should stay near the {}-byte cap, not grow with every print call",
            output.len(),
            MCP_EXECUTE_MAX_OUTPUT_BYTES,
        );
    }

    #[tokio::test]
    async fn execute_bound_function_call_matches_the_same_verb_call_the_gateway_makes_directly() {
        let gateway = fake(Ok(json!({"contract": "fgos.v1", "data": {"work": {"tsk-1": {"id": "tsk-1"}}}})));
        let script = r#"
            let r = get_work("tsk-1");
            print(r.data.work["tsk-1"].id);
        "#;
        let result = tokio::task::spawn_blocking(move || run_script(gateway, script)).await.unwrap();
        let output = result.unwrap();
        assert!(output.contains("tsk-1"), "expected bound function's real envelope data in output, got: {output}");
    }

    #[tokio::test]
    async fn execute_move_work_rejects_a_dash_prefixed_to_before_it_ever_reaches_the_verb_chokepoint() {
        let gateway = fake(Ok(json!({"ok": true})));
        let script = r#"move_work("tsk-1", "--delivered", "")"#;
        let result = tokio::task::spawn_blocking(move || run_script(gateway, script)).await.unwrap();
        assert!(
            result.is_err(),
            "a dash-prefixed 'to' value must be refused as validation, never reach the verb chokepoint where it could be misread as a flag"
        );
    }

    #[tokio::test]
    async fn execute_answer_work_forwards_approve_when_passed_as_third_argument() {
        let capturing = Arc::new(CapturingGateway {
            captured: std::sync::Mutex::new(Vec::new()),
            response: Ok(json!({"contract": "fgos.v1", "data": {}})),
        });
        let gateway: Arc<dyn VerbGateway> = capturing.clone();
        let script = r#"
            answer_work("tsk-1", "plain answer");
            answer_work("tsk-2", "approved answer", true);
            answer_work("tsk-3", "disapproved answer", false);
        "#;
        let result = tokio::task::spawn_blocking(move || run_script(gateway, script)).await.unwrap();
        assert!(result.is_ok(), "script error: {:?}", result.err());
        let captured = capturing.captured.lock().unwrap();
        assert_eq!(captured.len(), 3);
        assert_eq!(captured[0], vec!["answer", "tsk-1", "--text", "plain answer", "--json"]);
        assert_eq!(captured[1], vec!["answer", "tsk-2", "--text", "approved answer", "--approve", "--json"]);
        assert_eq!(captured[2], vec!["answer", "tsk-3", "--text", "disapproved answer", "--json"]);
    }

    #[tokio::test]
    async fn execute_script_outside_the_bound_function_allowlist_fails_cleanly_not_a_panic() {
        let gateway = fake(Ok(json!({"ok": true})));
        // `open_file` is never registered -- Rhai's stdlib carries no
        // filesystem access by default, so this proves nothing beyond the
        // bound allowlist is reachable, without ever touching a real file.
        let script = r#"open_file("/etc/passwd")"#;
        let result = tokio::task::spawn_blocking(move || run_script(gateway, script)).await.unwrap();
        assert!(result.is_err(), "expected a clean script error, got Ok");
    }

    #[tokio::test]
    async fn execute_a_failing_verb_call_surfaces_as_a_tool_error_not_a_panic() {
        let gateway = fake(Err("bad input".to_string()));
        let script = r#"list_work("", "", false)"#;
        let result = tokio::task::spawn_blocking(move || run_script(gateway, script)).await.unwrap();
        assert!(result.is_err());
    }

    #[tokio::test]
    async fn concurrent_execute_calls_do_not_interfere_with_each_other() {
        let gateway = fake(Ok(json!({"contract": "fgos.v1", "data": {"n": 1}})));
        let mut handles = Vec::new();
        for i in 0..8 {
            let gw = gateway.clone();
            handles.push(tokio::task::spawn_blocking(move || {
                run_script(gw, &format!("print({i}); graph()"))
            }));
        }
        for h in handles {
            assert!(h.await.unwrap().is_ok());
        }
    }
}

import { useMemo, useState, type FormEvent } from 'react'
import { createApiClient } from './api/client'
import { GatewayApiError, GatewayUnreachableError } from './api/errors'
import { Taskboard } from './screens/Taskboard'
import { TaskDetail } from './screens/TaskDetail'
import { NeedsAnswer } from './screens/NeedsAnswer'

// tsk-5jr: same-origin default -- the web bundle is served by the SAME
// gateway process it talks to (tsk-48w's with_static_serving, same port
// as build_router), so `window.location.origin` is the right default.
// Still overridable (area spec R1: the client must not assume one fixed
// origin) via ?gateway=<baseUrl> for local dev (`npm run dev` runs on a
// different port from the gateway it points at).
function defaultBaseUrl(): string {
  const override = new URLSearchParams(window.location.search).get('gateway')
  if (override) return override
  return `${window.location.origin}/v1`
}

const TOKEN_STORAGE_KEY = 'herdr-gateway-token'

type View = { name: 'board' } | { name: 'detail'; itemId: string } | { name: 'needs-answer' }

// S01 — Sign in (docs/ui-spec/screens/S01-sign-in.md). "The first and
// only door" -- one field, one credential, exchanged for a session by a
// real request (tsk-51i, D16/D17's own design pass): a token that is
// simply the wrong shape/value never gets stored, it is proven against
// the gateway first (`GET /state/digest`, the cheapest authenticated
// read that exists) so ERR-AUTH is a real rejection, not a client-side
// guess. R3: the error message never varies with the cause.
export default function App() {
  const [token, setToken] = useState<string | null>(() => window.localStorage.getItem(TOKEN_STORAGE_KEY))
  const [draftToken, setDraftToken] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [authError, setAuthError] = useState(false)
  const [view, setView] = useState<View>({ name: 'board' })
  const baseUrl = useMemo(defaultBaseUrl, [])

  if (!token) {
    async function signIn(e: FormEvent): Promise<void> {
      e.preventDefault()
      if (!draftToken || submitting) return
      setSubmitting(true)
      setAuthError(false)
      try {
        await createApiClient({ baseUrl, token: draftToken }).stateDigest()
        window.localStorage.setItem(TOKEN_STORAGE_KEY, draftToken)
        setToken(draftToken)
      } catch (err) {
        // R3: one message, same words, regardless of which half of the
        // credential was wrong or whether the gateway rejected it for a
        // different reason -- this screen must never become an oracle.
        if (err instanceof GatewayApiError || err instanceof GatewayUnreachableError) {
          setAuthError(true)
        } else {
          throw err
        }
      } finally {
        setSubmitting(false)
      }
    }

    return (
      <div className="flex min-h-svh items-center justify-center bg-bg px-4">
        <form
          className="flex w-full max-w-sm flex-col items-center gap-6 rounded-xl border border-border bg-surface p-8 shadow-sm"
          onSubmit={signIn}
        >
          <div className="text-center">
            <h1 className="font-mono text-2xl font-bold text-brand">herdr</h1>
            <p className="mt-1 text-sm text-ink-muted">fgOS work dashboard</p>
          </div>

          <label className="flex w-full flex-col gap-1.5 text-sm font-medium text-ink">
            Access token
            <input
              type="password"
              data-testid="token-input"
              className="w-full rounded-lg border border-border bg-surface px-3 py-2 text-sm text-ink outline-none focus:border-brand focus:ring-2 focus:ring-brand/20"
              value={draftToken}
              onChange={(e) => setDraftToken(e.target.value)}
              placeholder="••••••••••••••••••••••••"
              readOnly={submitting}
              autoFocus
            />
          </label>

          <button
            type="submit"
            data-testid="token-submit"
            disabled={!draftToken || submitting}
            className="w-full rounded-lg bg-brand px-4 py-2 text-sm font-semibold text-brand-contrast transition hover:bg-brand-dark disabled:cursor-not-allowed disabled:opacity-40"
          >
            {submitting ? 'Signing in…' : 'Sign in'}
          </button>

          <div className="min-h-[1.25rem] text-sm text-danger" data-testid="auth-error-slot">
            {authError && <span data-testid="auth-error">Sign-in failed.</span>}
          </div>

          <p className="text-center text-xs text-ink-muted">Reachable beyond this machine.</p>
        </form>
      </div>
    )
  }

  const client = createApiClient({ baseUrl, token })

  if (view.name === 'detail') {
    return (
      <TaskDetail
        client={client}
        baseUrl={baseUrl}
        itemId={view.itemId}
        onBack={() => setView({ name: 'board' })}
      />
    )
  }

  if (view.name === 'needs-answer') {
    return (
      <NeedsAnswer
        client={client}
        baseUrl={baseUrl}
        onOpenItem={(id) => setView({ name: 'detail', itemId: id })}
        onBack={() => setView({ name: 'board' })}
      />
    )
  }

  return (
    <Taskboard
      client={client}
      baseUrl={baseUrl}
      onSelectItem={(id) => setView({ name: 'detail', itemId: id })}
      onOpenNeedsAnswer={() => setView({ name: 'needs-answer' })}
    />
  )
}

import { GatewayApiError, GatewayUnreachableError } from './errors'
import type {
  DigestEnvelope,
  Envelope,
  ErrorEnvelope,
  ListReadyData,
  ListWorkData,
  ListWorkParams,
  PageParams,
  RunnerTickData,
  Session,
  SessionSlotsData,
  WorkDetail,
  WorkDocsData,
  WorkItem,
} from './types'

// Area spec R1 / item scope: base URL and token are constructor
// parameters, never a module-level constant -- the client must be able to
// address more than one gateway.
export interface ApiClientConfig {
  baseUrl: string
  token: string
}

async function rawFetch(config: ApiClientConfig, path: string, init?: RequestInit): Promise<Response> {
  try {
    return await fetch(`${config.baseUrl}${path}`, {
      ...init,
      headers: {
        ...(init?.body ? { 'Content-Type': 'application/json' } : {}),
        ...init?.headers,
        // D13: Authorization: Bearer <token>, the one auth mechanism this
        // cluster locked -- never a cookie.
        Authorization: `Bearer ${config.token}`,
      },
    })
  } catch (cause) {
    // fetch() only rejects on a network-level failure (MDN), never on an
    // HTTP error status -- this catch is exactly the gateway-unreachable
    // case, distinct from the !response.ok branch below.
    throw new GatewayUnreachableError(cause)
  }
}

async function parseErrorEnvelope(response: Response): Promise<ErrorEnvelope> {
  try {
    return (await response.json()) as ErrorEnvelope
  } catch {
    return { category: 'unexpected', message: `HTTP ${response.status} with a non-JSON body` }
  }
}

async function request<T>(config: ApiClientConfig, path: string, init?: RequestInit): Promise<T> {
  const response = await rawFetch(config, path, init)
  if (!response.ok) {
    throw new GatewayApiError(await parseErrorEnvelope(response))
  }
  const envelope = (await response.json()) as Envelope<T>
  return envelope.data
}

function query(params?: object): string {
  if (!params) return ''
  const entries = Object.entries(params).filter(([, v]) => v !== undefined)
  if (entries.length === 0) return ''
  const search = new URLSearchParams(entries.map(([k, v]) => [k, String(v)]))
  return `?${search.toString()}`
}

function jsonBody(body: unknown): RequestInit {
  return { method: 'POST', body: JSON.stringify(body) }
}

/**
 * Typed wrapper over docs/contracts/fgos-gateway-api-v1.yaml -- one
 * function per operationId, never a re-description of an endpoint's own
 * shape. `/contract` (unauthenticated, non-enveloped) is intentionally
 * NOT wrapped here: a client fetches it once, before it has a client
 * configured at all, per the contract's own top-level note.
 */
export function createApiClient(config: ApiClientConfig) {
  return {
    // GET /work (fgos-gateway-api-v1.yaml:105-148)
    listWork: (params?: ListWorkParams) => request<ListWorkData>(config, `/work${query(params)}`),

    // POST /work (fgos-gateway-api-v1.yaml:150-181)
    submitWork: (text: string) => request<WorkItem>(config, '/work', jsonBody({ text })),

    // GET /work/{id} (fgos-gateway-api-v1.yaml:186-203)
    // tsk-4id: corrected return type from WorkItem to WorkDetail -- the
    // real response includes discovery/decisions/gates/outcome/friction/
    // settlement/learning, not just the WorkItem subset (contract fixed
    // to match, see fgos-gateway-api-v1.yaml's own WorkDetail schema).
    getWork: (id: string) => request<WorkDetail>(config, `/work/${encodeURIComponent(id)}`),

    // GET /work/{id}/docs (tsk-4id) -- CONTEXT.md/plan.md raw content.
    getWorkDocs: (id: string) => request<WorkDocsData>(config, `/work/${encodeURIComponent(id)}/docs`),

    // POST /work/{id}/move (fgos-gateway-api-v1.yaml:205-224)
    moveWork: (id: string, to: string, expect?: string) =>
      request<WorkItem>(config, `/work/${encodeURIComponent(id)}/move`, jsonBody({ to, expect })),

    // POST /work/{id}/ask (fgos-gateway-api-v1.yaml:226-244)
    askWork: (id: string, text: string) =>
      request<WorkItem>(config, `/work/${encodeURIComponent(id)}/ask`, jsonBody({ text })),

    // POST /work/{id}/answer (fgos-gateway-api-v1.yaml:246-264)
    answerWork: (id: string, text: string, approve?: boolean) =>
      request<WorkItem>(
        config,
        `/work/${encodeURIComponent(id)}/answer`,
        jsonBody({ text, ...(approve !== undefined ? { approve } : {}) }),
      ),

    // POST /work/{id}/take (fgos-gateway-api-v1.yaml:266-289)
    takeWork: (id: string, role: 'human' | 'session' = 'session') =>
      request<WorkItem>(config, `/work/${encodeURIComponent(id)}/take`, jsonBody({ role })),

    // POST /work/{id}/return (fgos-gateway-api-v1.yaml:291-300)
    returnWork: (id: string) => request<WorkItem>(config, `/work/${encodeURIComponent(id)}/return`, { method: 'POST' }),

    // POST /work/{id}/approve (fgos-gateway-api-v1.yaml:302-312)
    approveWork: (id: string) => request<WorkItem>(config, `/work/${encodeURIComponent(id)}/approve`, { method: 'POST' }),

    // POST /work/{id}/reject (fgos-gateway-api-v1.yaml:314-332)
    rejectWork: (id: string, reason: string) =>
      request<WorkItem>(config, `/work/${encodeURIComponent(id)}/reject`, jsonBody({ reason })),

    // GET /ready (fgos-gateway-api-v1.yaml:334-361)
    listReady: (params?: PageParams) => request<ListReadyData>(config, `/ready${query(params)}`),

    // GET /rollup/{id} (fgos-gateway-api-v1.yaml:363-382) -- opaque shape
    // per the contract itself ("Rollup shape, opaque to this contract").
    rollupWork: (id: string) => request<Record<string, unknown>>(config, `/rollup/${encodeURIComponent(id)}`),

    // GET /graph (fgos-gateway-api-v1.yaml:384-401) -- opaque shape.
    workGraph: () => request<Record<string, unknown>>(config, '/graph'),

    // GET /state/digest (fgos-gateway-api-v1.yaml:403-429) -- no `data`
    // field; see poll.ts for the cheap-poll helper built on this.
    stateDigest: async (): Promise<DigestEnvelope> => {
      const response = await rawFetch(config, '/state/digest')
      if (!response.ok) {
        throw new GatewayApiError(await parseErrorEnvelope(response))
      }
      return (await response.json()) as DigestEnvelope
    },

    // POST /sessions (fgos-gateway-api-v1.yaml:431-460)
    startSession: (item?: string) => request<Session>(config, '/sessions', jsonBody(item ? { item } : {})),

    // DELETE /sessions/{sessionId} (fgos-gateway-api-v1.yaml:462-483)
    endSession: (sessionId: string, force = false) =>
      request<unknown>(config, `/sessions/${encodeURIComponent(sessionId)}${query({ force: force || undefined })}`, {
        method: 'DELETE',
      }),

    // GET /sessions/{sessionId}/slots (fgos-gateway-api-v1.yaml:485-521)
    sessionSlots: (sessionId: string) =>
      request<SessionSlotsData>(config, `/sessions/${encodeURIComponent(sessionId)}/slots`),

    // POST /runner/tick (fgos-gateway-api-v1.yaml:523-558). The 429
    // "runner busy" case is still an ErrorEnvelope body (category
    // `busy`), so it already flows through the same GatewayApiError path
    // as every other non-2xx response -- no special-casing needed here.
    runnerTick: () => request<RunnerTickData>(config, '/runner/tick', { method: 'POST' }),
  }
}

export type ApiClient = ReturnType<typeof createApiClient>

import type { ErrorEnvelope } from './types'

// Area spec Edge Cases Settled (docs/specs/herdr-web-dashboard.md:259-260):
// "The gateway is unreachable. The client says so plainly and offers to
// retry; it never presents stale data as current." A network-level fetch
// failure (bad host, connection refused, DNS failure, offline) throws
// before a Response ever exists -- MDN Window/fetch: "A fetch() promise
// only rejects when the request fails ... because of a badly-formed
// request URL or a network error." This is the type that distinguishes
// that case from a normal HTTP error response.
export class GatewayUnreachableError extends Error {
  constructor(cause: unknown) {
    super('gateway unreachable')
    this.name = 'GatewayUnreachableError'
    this.cause = cause
  }
}

// A resolved HTTP response whose status was not ok -- the gateway itself
// answered, with an fgos.v1 ErrorEnvelope body (fgos-gateway-api-v1.yaml
// components.responses.Error). Callers branch on `category`, never on
// `message` text (the contract's own explicit rule).
export class GatewayApiError extends Error {
  readonly category: ErrorEnvelope['category']
  readonly exitCode?: number

  constructor(envelope: ErrorEnvelope) {
    super(envelope.message ?? envelope.category)
    this.name = 'GatewayApiError'
    this.category = envelope.category
    this.exitCode = envelope.exitCode
  }
}

