import type { ApiClient } from './client'

// D9 (docs/history/herdr-web-dashboard-plan-realignment/CONTEXT.md): the
// gateway has no SSE/WebSocket, only GET /state/digest's cheap-poll
// `data_hash` -- this helper is the poll-driven half of that pattern. A
// caller holds the returned digest and calls `poll` again on its own
// interval; `changed` tells it whether a full re-fetch of a read endpoint
// is worth doing.

export interface PollResult {
  dataHash: string
  changed: boolean
}

/**
 * Calls GET /state/digest once and compares against `previousDataHash`
 * (pass `undefined` on the first call -- always reports `changed: true`
 * then, since there is nothing to compare against yet).
 */
export async function pollStateDigest(client: ApiClient, previousDataHash?: string): Promise<PollResult> {
  const digest = await client.stateDigest()
  return {
    dataHash: digest.data_hash,
    changed: previousDataHash === undefined || digest.data_hash !== previousDataHash,
  }
}

// Types mirrored from docs/contracts/fgos-gateway-api-v1.yaml (tsk-yo0
// scope: "KHÔNG tự mô tả lại endpoint" -- every shape here traces to a
// specific path in that contract, never invented independently.

export interface Envelope<T> {
  contract: 'fgos.v1'
  generated_at: string
  data_hash: string
  data: T
}

// GET /state/digest -- the one response with no `data` field
// (fgos-gateway-api-v1.yaml:403-429).
export interface DigestEnvelope {
  contract: 'fgos.v1'
  generated_at: string
  data_hash: string
}

// components.schemas.ErrorEnvelope (fgos-gateway-api-v1.yaml:663-689) --
// the closed category taxonomy CTR001 defines. Branch on `category` only,
// never on `message`.
export type ErrorCategory =
  | 'precondition'
  | 'conflict'
  | 'validation'
  | 'corrupt-log'
  | 'lock-timeout'
  | 'session-fail'
  | 'merge-fail'
  | 'busy'
  | 'unexpected'

export interface ErrorEnvelope {
  category: ErrorCategory
  message?: string
  exitCode?: number
}

// components.schemas.WorkItem (fgos-gateway-api-v1.yaml:630-652).
export interface WorkItem {
  id: string
  title: string
  description?: string
  kind: string
  status: string
  workflowStep?: string
  size?: string
  rigor?: string
  risk?: string
  domain?: string
  parent?: string | null
  deps?: string[]
  footprint?: string[]
  verify?: string
  docsRef?: string | null
}

// components.schemas.WorkDetail (fgos-gateway-api-v1.yaml) -- GET
// /work/{id}'s real `data` shape (tsk-4id).
export interface GateApproveRecord {
  actor: string
  at: string
  verify: string
}

export interface GatesInfo {
  contextApprove?: GateApproveRecord
  planApprove?: GateApproveRecord
  validateApprove?: GateApproveRecord
  ask?: string
  askHistory?: string[]
  answer?: string
  statusAtAsk?: string
}

export interface Decision {
  text: string
  rationale?: string
  source: string
  id: string
  ts: string
  kind?: string
}

export interface SettlementEntry {
  kind: string
  role: string
  ts: string
  detail: string | null
  id: string
}

export interface Settlement {
  count: number
  recent: SettlementEntry[]
}

export interface WorkDetail {
  work: WorkItem
  discovery?: unknown[]
  decisions?: Decision[]
  gates?: GatesInfo
  outcome?: unknown
  friction?: unknown
  settlement?: Settlement
  learning?: unknown
}

// GET /work/{id}/docs's own data shape (fgos-gateway-api-v1.yaml, tsk-4id).
export interface WorkDocsData {
  docsRef: string | null
  contextMd: string | null
  planMd: string | null
  narrativeMissing?: boolean
}

// components.schemas.Session (fgos-gateway-api-v1.yaml:654-661).
export interface Session {
  sessionId: string
  worktree: string
  branch: string
  item?: string | null
}

// components.schemas.Page (fgos-gateway-api-v1.yaml:622-628).
export interface Page {
  nextCursor?: string | null
}

// GET /work's own data shape (fgos-gateway-api-v1.yaml:139-146): a map
// keyed by id, NOT an array -- distinct from /ready below.
export interface ListWorkData extends Page {
  work: Record<string, WorkItem>
}

// GET /ready's own data shape (fgos-gateway-api-v1.yaml:352-359): an
// array, distinct from /work's map.
export interface ListReadyData extends Page {
  items: WorkItem[]
}

// GET /sessions/{sessionId}/slots (fgos-gateway-api-v1.yaml:505-521).
export interface SessionSlotsData {
  execution?: {
    occupied: number
    items: Array<{ id: string; sessionId: string; claimRole: string }>
  }
}

// POST /runner/tick (fgos-gateway-api-v1.yaml:549-551).
export interface RunnerTickData {
  dispatched: string[]
}

export interface ListWorkParams {
  status?: string
  step?: string
  all?: boolean
  cursor?: string
  limit?: number
}

export interface PageParams {
  cursor?: string
  limit?: number
}

// Shared by Taskboard.tsx and TaskDetail.tsx -- R5 (docs/specs/herdr-
// web-dashboard.md): "reachable on network" has no dedicated contract
// field (confirmed: no `bind` field anywhere in docs/contracts/
// fgos-gateway-api-v1.yaml), so the client's own configured `baseUrl` is
// the only observable signal.

const LOOPBACK_HOSTNAMES = new Set(['localhost', '127.0.0.1', '::1', '[::1]'])

export function isNonLoopbackHost(baseUrl: string): boolean {
  try {
    return !LOOPBACK_HOSTNAMES.has(new URL(baseUrl).hostname)
  } catch {
    return false
  }
}

export function hostOf(baseUrl: string): string {
  try {
    return new URL(baseUrl).host
  } catch {
    return baseUrl
  }
}

// Status → semantic color bucket, shared by Taskboard and TaskDetail so
// the same status always reads the same color everywhere (D16/D17,
// docs/history/herdr-web-dashboard/CONTEXT.md). The board GROUPS by the
// item's raw `status` string (src/state/work.mjs's STATUSES), not by
// this bucket -- this only decides which of the 4 mockup colors
// (amber/blue/slate/green) a given raw status renders with.

export interface StatusColor {
  text: string
  bg: string
  bar: string
  barBorder: string
}

// Literal class names throughout (never string-built at runtime) --
// Tailwind's JIT scanner only picks up classes it can find verbatim in
// source text.
const NEEDS_ANSWER = {
  text: 'text-status-needs-answer',
  bg: 'bg-status-needs-answer-bg',
  bar: 'bg-status-needs-answer-bar',
  barBorder: 'border-status-needs-answer-bar',
}
const IN_PROGRESS = {
  text: 'text-status-in-progress',
  bg: 'bg-status-in-progress-bg',
  bar: 'bg-status-in-progress-bar',
  barBorder: 'border-status-in-progress-bar',
}
const TODO = {
  text: 'text-status-todo',
  bg: 'bg-status-todo-bg',
  bar: 'bg-status-todo-bar',
  barBorder: 'border-status-todo-bar',
}
const DONE = {
  text: 'text-status-done',
  bg: 'bg-status-done-bg',
  bar: 'bg-status-done-bar',
  barBorder: 'border-status-done-bar',
}

const BUCKET: Record<string, StatusColor> = {
  'awaiting-human': NEEDS_ANSWER,
  'awaiting-approval': NEEDS_ANSWER,
  blocked: NEEDS_ANSWER,
  doing: IN_PROGRESS,
  retrospective: IN_PROGRESS,
  cleanup: IN_PROGRESS,
  todo: TODO,
  backlog: TODO,
  done: DONE,
  delivered: DONE,
}

export function statusColor(status: string): StatusColor {
  return BUCKET[status] ?? TODO
}
